-- Azshara: creature abilities
-- Azshara is the Cataclysm revamp and most of its creatures (Spitelash, Talrendis, Legashi, Blackmaw, the gnomes of Ruins of
-- Eldarath, Twilight, the wildlife) had no AI. Port their abilities from the Cataclysm data, and from the classic data where
-- Cataclysm has none (the Makrinni Scrabbler, Scalebeard, and the old level 50s rares Monnos, Hawkhelm and Feardred), keeping the
-- quest scripts already in place.

SET @ENTRIES := '830,6118,6190,6193,6194,6195,6196,6200,6201,6202,6350,6352,6370,6372,6375,6377,6646,6647,6648,6649,6650,6651,6652,7885,7886,8408,8660,8761,8764,13896,35095,35096,35111,35149,35177,35190,35198,35245,35312,35371,35466,35558,35584,35759,35831,35832,35833,35880,35881,36012,36013,36015,36131,36147,36304,36384,36385,36407,36592,36593,36594,36611,36614,36636,36637,36638,36660,36680,36688,36752,36815,36816,36822,36849,36868,36873,36884,36890,36914,36925,36936,36972,36975,36976,36989,37002,37740,37741,42777';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '14881,36639,51508,51509,52018';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
